Q: SortableJS: hard to drop an item into a parent when dragging the last item of a wrapped row A: <p>You could add a <code>spacer</code> element and give it the width of the element your sorting while setting the width to 0 when the element is sorted to the left or upwards:</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>const containers = document.querySelectorAll(".list-group");

const spacer = document.createElement("div"); 
spacer.className = "spacer";

containers.forEach((container) =&gt; {
  new Sortable(container, {
    group: "nested",
    direction: "horizontal",
    animation: 150,

    swapThreshold: 0.6,
    emptyInsertThreshold: 10,

    onStart(evt) {
      document.body.style.cursor = "grabbing";
      spacer.style.minWidth = `${evt.item.offsetWidth}px`;
      evt.from.insertBefore(spacer, evt.from.children[evt.oldIndex]);
    },
    onEnd() {
      if (spacer) spacer.remove();    
      document.body.style.cursor = "default";
    }
  });
});</code></pre>
<pre class="snippet-code-css lang-css prettyprint-override"><code>body {
  font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
  padding: 20px;
  background-color: #f3f3f3;
}

h1 {
  text-align: center;
  margin-bottom: 30px;
}

/* ------------------------------
   LIST CONTAINERS
------------------------------ */

.list-group {
  position: relative;
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  align-items: flex-start;
  align-content: flex-start;

  gap: 10px;
  padding: 15px;

  min-height: 80px;
  background-color: #e0e0e0;
  border-radius: 8px;
  border: 1px dashed #aaa;
}

/* Nested container */
.nested-list {
  margin-top: 10px;
  min-height: 20px;
  padding: 10px;

  background-color: rgba(255, 255, 255, 0.6);
  border: 1px dotted #999;
}

/* ------------------------------
   ITEMS
------------------------------ */

.list-item {
  position: relative;
  display: flex;
  flex-direction: column;

  padding: 15px;
  min-width: 50px;

  background-color: #fff;
  border: 1px solid #ccc;
  border-radius: 4px;

  cursor: grab;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.05);
}

/* Nested items */
.list-item.nested {
  background-color: #d1e7dd;
  border-color: #a3cfbb;
}

/* Parent items */
.parent-item {
  background-color: #fff3cd;
  border-color: #ffecb5;
}

/* ------------------------------
   SORTABLE HELPERS
------------------------------ */
.spacer {
  align-self: stretch;
}

.sortable-ghost ~ .spacer {
  min-width: 0 !important;
}

/* Ghost (placeholder from SortableJS) */
.sortable-ghost {
  visibility: hidden;
}

/* Dragging element */
.sortable-drag {
  cursor: grabbing;
  opacity: 0.9;
}

/* Layout spacer (our placeholder) */
.layout-preserver {
  visibility: hidden;
  pointer-events: none;
  flex: 0 0 auto;
  box-sizing: border-box;
}</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;html&gt;

&lt;head&gt;
  &lt;title&gt;Horizontal Nested Sortable&lt;/title&gt;

  &lt;link rel="stylesheet" href="style.css"&gt;

  &lt;script src="https://cdn.jsdelivr.net/npm/sortablejs@latest/Sortable.min.js"&gt;&lt;/script&gt;
&lt;/head&gt;

&lt;body&gt;

  &lt;h1&gt;Nested Sortable&lt;/h1&gt;

  &lt;!-- Root container --&gt;
  &lt;div id="root-list" class="list-group"&gt;

    &lt;div class="list-item"&gt;Item element 1&lt;/div&gt;
    &lt;div class="list-item"&gt;Item element 2&lt;/div&gt;

    &lt;!-- Parent item --&gt;
    &lt;div class="list-item parent-item"&gt;
      &lt;div class="item-content"&gt;
        &lt;strong&gt;Item 3 (Parent)&lt;/strong&gt;
      &lt;/div&gt;

      &lt;!-- Nested list --&gt;
      &lt;div class="list-group nested-list"&gt;
        &lt;div class="list-item nested"&gt;Sub-item 3.1&lt;/div&gt;
        &lt;div class="list-item nested"&gt;Sub-item 3.2&lt;/div&gt;
        &lt;div class="list-item nested"&gt;Sub-item 3.3&lt;/div&gt;
        &lt;div class="list-item nested"&gt;Sub-item 3.4&lt;/div&gt;
      &lt;/div&gt;
    &lt;/div&gt;

    &lt;div class="list-item"&gt;Item element 4&lt;/div&gt;

    &lt;!-- Parent with nested list containing Item 6 --&gt;
    &lt;div class="list-item parent-item"&gt;
      &lt;div class="item-content"&gt;
        &lt;strong&gt;Item 5 (Parent)&lt;/strong&gt;
      &lt;/div&gt;

      &lt;div class="list-group nested-list"&gt;
        &lt;div class="list-item nested"&gt;Item element 6&lt;/div&gt;
      &lt;/div&gt;
    &lt;/div&gt;

  &lt;/div&gt;

  &lt;script src="script.js"&gt;&lt;/script&gt;
&lt;/body&gt;

&lt;/html&gt;</code></pre>
